//! Lookup tables of Maschine's Sampler (`NI::MASCOMMON::SAMPLER` / `RT::SamplerProcessor`), read from the
//! Maschine 3 arm64 binary. Each has 128 entries indexed by a normalized parameter `v` (0..1):
//! `i = min(v * 127, 127)`, linear interpolation between `T[floor(i)]` and `T[floor(i) + 1]` (no
//! interpolation at the last entry). See docs/sampler-dsp.md.

/// `lerp(T, v)`: the tables' lookup, as the Sampler does it.
pub fn lookup(t: &[f32; 128], v: f32) -> f32 {
    let x = (v * 127.0).clamp(0.0, 127.0);
    let i = x as usize;
    if i < 127 { t[i] + (x - i as f32) * (t[i + 1] - t[i]) } else { t[127] }
}

